#nullable enable
using JasperFx.Events.Daemon;
using JasperFx.Events.Projections;
using Marten;
// ISubscription is in Marten.Subscriptions, EventRange in JasperFx.Events.Projections,
// ISubscriptionController in JasperFx.Events.Daemon, and NullChangeListener in Marten itself. No doc page
// states any of them — settled by reflecting over the assemblies, which is the tiebreaker when the docs and
// the compiler disagree.
using Marten.Subscriptions;
using Wolverine;
using Wolverine.Marten;
using EmailOutbox.Contracts;

namespace EmailOutbox.Automation;

/// <summary>
/// The one thing the model does not tell you about an automation slice, and the reason this folder exists.
///
/// <c>Event(s) -> View -> Trigger -> Command</c> constrains the CONTRACT: the trigger decides from
/// accumulated state rather than one event's payload, and issues a command rather than appending. It says
/// nothing about what wakes the trigger, and it does not require the View to be a materialised projection —
/// a subscription's checkpoint is a record of what has been worked; a durable inbox is a list of pending
/// work. The green box on the diagram is the concept.
///
/// **In a real project you would pick ONE and delete the rest.** All four live here because this is a
/// reference: they are selected by <c>Automation:Wakeup</c> so the same six tests can be run against each,
/// which is what makes this a comparison rather than four programs.
///
/// <code>
///   the trigger event is OURS, appended in our own transaction   -> Forwarding    (the common case)
///   ours, and ordering or replay matters                         -> Subscription
///   ours, and the decision is a function of the VIEW ROW         -> SideEffects
///   the trigger event is FOREIGN — we never append it            -> Sweep
///   there is no event at all — the trigger is TIME               -> Sweep
/// </code>
///
/// Whatever the choice, it ends up sending <see cref="RunSendEmail"/>. Keeping that seam is what lets a test
/// drive the same path production does — and while a trigger was reachable only over HTTP, "nothing ever
/// wakes this in production" stayed invisible to a green suite.
/// </summary>
public static class SendEmailWakeup
{
    public const string Setting = "Automation:Wakeup";

    public enum Mechanism { None, Forwarding, Subscription, SideEffects, Sweep }

    /// <summary>
    /// Read once, from configuration, so every hook agrees. <c>None</c> in tests: a clock or a doorbell
    /// firing mid-test appends events into streams other tests are asserting on, and every GIVEN becomes a
    /// race. The per-mechanism tests each boot their own host with one of these switched on.
    /// </summary>
    public static Mechanism Chosen { get; private set; } = Mechanism.None;

    private static Mechanism Read(IConfiguration config) =>
        (config[Setting] ?? "").Trim().ToLowerInvariant() switch
        {
            "forwarding" => Mechanism.Forwarding,
            "subscription" => Mechanism.Subscription,
            "sideeffects" or "side-effects" => Mechanism.SideEffects,
            "sweep" => Mechanism.Sweep,
            _ => Mechanism.None,          // includes "false", which is what the test fixture sets
        };

    /// <summary>
    /// Resolves the choice, and is called FIRST — before every Configure hook below asks for it.
    ///
    /// This ordering is load-bearing and it bit here. When the choice was resolved in RegisterServices (which
    /// the generator emits LAST, after all four Configure hooks), forwarding set UseFastEventForwarding on an
    /// integration callback that had already run while Chosen was still None. No error, nothing logged, and
    /// the automation simply never woke — the exact failure this folder exists to document, reproduced in the
    /// folder's own plumbing. Only the test that checks a REAL wakeup caught it.
    /// </summary>
    public static void Choose(IConfiguration config) => Chosen = Read(config);

    /// <summary>Hosted services and anything needing the app builder. The clock lives here.</summary>
    public static void RegisterServices(WebApplicationBuilder builder)
    {
        if (Chosen == Mechanism.Sweep)
            builder.Services.AddSingleton<IHostedService>(sp => new SweepClock(sp));
    }

    /// <summary>
    /// The lifecycle of this slice's todo View.
    ///
    /// SIDE EFFECTS FORCE ASYNC, and that is the first real cost of mechanism C. Marten documents side
    /// effects as built for continuous asynchronous projection processing: RaiseSideEffects is not called
    /// for an Inline projection at all unless EnableSideEffectsOnInlineProjections is switched on, and the
    /// docs describe that as a late addition for a single client. Async is the supported path.
    ///
    /// The consequence lands on everything downstream. The todo View stops being updated in the same
    /// transaction as the append, so it is EVENTUALLY consistent — a test that reads it has to wait rather
    /// than assert. Every other mechanism here keeps the view Inline and pays none of that.
    /// </summary>
    public static ProjectionLifecycle LifecycleOf(ProjectionLifecycle fallback) =>
        Chosen == Mechanism.SideEffects ? ProjectionLifecycle.Async : fallback;

    /// <summary>Marten options: a projection lifecycle, a subscription registration.</summary>
    public static void ConfigureMarten(StoreOptions opts)
    {
        // SideEffects would need this, and it is the first question to settle when implementing it:
        //   opts.Events.EnableSideEffectsOnInlineProjections = true;
        // Marten documents side effects as built for ASYNC projection processing, with inline support added
        // later for one client. If inline turns out to be unsound, the projection moves to Async and every
        // test for that mechanism becomes eventually-consistent — a cost worth measuring rather than
        // assuming.
    }

    /// <summary>The store: AddAsyncDaemon, which a subscription and an async projection both need.</summary>
    public static void ConfigureStore(MartenServiceCollectionExtensions.MartenConfigurationExpression marten)
    {
        // The daemon runs both an async projection and a subscription, so it is what makes C and B possible
        // at all. Switched on only for the mechanisms that need it: it is a background thread, and enabling
        // it for the others would make their tests eventually-consistent for nothing.
        //
        // Solo rather than HotCold: one node, no leader election, much faster startup.
        if (Chosen is Mechanism.SideEffects or Mechanism.Subscription)
            marten.AddAsyncDaemon(DaemonMode.Solo);

        // SUBSCRIPTION. Registered through the IoC container because it needs IMessageBus; Scoped, so Marten
        // builds one per page and the bus comes from that same scope.
        //
        // IncludeType is not just an optimisation — it is the statement of intent. This subscription cares
        // about EmailPrepared and nothing else, so Marten never fetches the rest. Note what is NOT filtered
        // in: EmailSent. Subscribing to the automation own output would wake the trigger with its completion.
        if (Chosen == Mechanism.Subscription)
            marten.AddSubscriptionWithServices<SendEmailSubscription>(
                ServiceLifetime.Singleton,
                o => o.IncludeType<EmailPrepared>());
    }

    /// <summary>
    /// FORWARDING, part one. Wolverine pushes any event Marten captures through its outbox where a known
    /// subscriber exists — and a subscriber is exactly what <see cref="Doorbell"/> is. Delivery happens once
    /// the containing transaction commits, so the Inline projection the trigger reads is already up to date.
    ///
    /// Only events THIS app appends are forwarded. That is precisely why forwarding could not wake the
    /// automation in the retired example, whose trigger event was foreign — and why it can wake this one.
    /// </summary>
    public static void ConfigureIntegration(MartenIntegration integration)
    {
        if (Chosen == Mechanism.Forwarding) integration.UseFastEventForwarding = true;
    }

    /// <summary>Wolverine options: discovery, policies, whatever a doorbell handler needs.</summary>
    public static void ConfigureWolverine(WolverineOptions opts)
    {
        // Conventional discovery only finds *Handler / *Consumer, and Doorbell is neither.
        if (Chosen == Mechanism.Forwarding) opts.Discovery.IncludeType(typeof(Doorbell));
    }

    /// <summary>
    /// FORWARDING, part two: the doorbell.
    ///
    /// It takes the event and **uses nothing from it**. That restraint is the whole difference between an
    /// automation and an event handler: the event says *something happened, go look*, and the trigger then
    /// decides from the View. Read <c>e.To</c> here and the todo list becomes decoration, the View stops
    /// being the record of pending work, and this is <c>Event -> Processor -> Event</c> wearing a hat.
    ///
    /// The parameter is needed to make this a subscriber at all — that is what tells Wolverine to forward
    /// the event type. Discarded immediately, and named to say so.
    /// </summary>
    public static class Doorbell
    {
        public static Task Handle(EmailPrepared _, IMessageBus bus) => bus.InvokeAsync(new RunSendEmail());
    }

    /// <summary>
    /// SWEEP: a clock, and nothing more.
    ///
    /// The durable state is the todo View, not the clock — a run recomputes its work from pending rows every
    /// time, so a restart loses nothing and the interval is a free choice. That is why this is a plain loop
    /// rather than a durable self-rescheduling message: six attempts at the latter all failed silently on
    /// this stack, and it turned out to buy nothing the View was not already providing.
    ///
    /// IHostedLifecycleService, not IHostedService: StartedAsync runs after every hosted service has
    /// started, so Wolverine and the Marten schema are both up before the first run.
    /// </summary>
    public sealed class SweepClock(IServiceProvider services) : IHostedLifecycleService, IAsyncDisposable
    {
        private readonly CancellationTokenSource _stopping = new();
        private Task? _loop;

        public static readonly TimeSpan Interval = TimeSpan.FromSeconds(
            double.TryParse(Environment.GetEnvironmentVariable("AUTOMATION_SWEEP_SECONDS"), out var s) ? s : 30);

        public Task StartedAsync(CancellationToken cancellation)
        {
            _loop = RunAsync();
            return Task.CompletedTask;     // must return, or the host never finishes starting
        }

        private async Task RunAsync()
        {
            using var timer = new PeriodicTimer(Interval);
            var logger = services.GetRequiredService<ILoggerFactory>().CreateLogger<SweepClock>();

            while (await timer.WaitForNextTickAsync(_stopping.Token).ConfigureAwait(false))
            {
                try
                {
                    await using var scope = services.CreateAsyncScope();
                    await scope.ServiceProvider.GetRequiredService<IMessageBus>()
                        .InvokeAsync(new RunSendEmail(), _stopping.Token);
                }
                catch (OperationCanceledException) when (_stopping.IsCancellationRequested) { return; }
                catch (Exception e)
                {
                    // One failed run must never kill the clock: the next tick re-reads the View and the work
                    // is still pending, so recovery is automatic. A clock that dies on a transient error is
                    // indistinguishable from one that finished its work.
                    logger.LogError(e, "send-email sweep failed. Continuing.");
                }
            }
        }

        public async Task StoppingAsync(CancellationToken cancellation)
        {
            await _stopping.CancelAsync();
            if (_loop is not null) await _loop.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
        }

        public async ValueTask DisposeAsync()
        {
            await StoppingAsync(CancellationToken.None);
            _stopping.Dispose();
        }

        public Task StartingAsync(CancellationToken cancellation) => Task.CompletedTask;
        public Task StartAsync(CancellationToken cancellation) => Task.CompletedTask;
        public Task StopAsync(CancellationToken cancellation) => Task.CompletedTask;
        public Task StoppedAsync(CancellationToken cancellation) => Task.CompletedTask;
    }
}

/// <summary>
/// MECHANISM B: a Marten subscription — the async daemon pushes committed events at this, in order, with a
/// durable checkpoint recording how far it has got.
///
/// WHAT IT UNIQUELY OFFERS, and the only reason to prefer it over forwarding:
///
///   ORDER      events arrive in sequence order, not "as soon as possible". Forwarding explicitly gives no
///              ordering guarantee; a subscription does.
///   REPLAY     the checkpoint is a row in the database, so it can be rewound. A doorbell that was never
///              delivered is simply lost; a subscription that was offline catches up.
///   BACKLOG    it starts from wherever its checkpoint is, so events appended while the app was down are
///              processed on the next start. Forwarding only ever sees live traffic.
///
/// WHAT IT COSTS: the async daemon, a background thread — and therefore the same startup weight as C, though
/// notably NOT the same consistency cost. The todo View stays <c>Inline</c>, updated in the append's own
/// transaction, so by the time the daemon hands this subscription the event the row is already committed and
/// the trigger reads a current View. That is the concrete advantage over side effects, which force the view
/// Async to get called at all.
///
/// It is also entirely OUTSIDE the read model, unlike C: a registration and a class, and the projection is
/// left alone.
/// </summary>
public sealed class SendEmailSubscription(IServiceProvider services) : ISubscription
{
    /// <summary>
    /// One message per PAGE, not per event — and that is deliberate rather than lazy.
    ///
    /// The trigger reads the whole todo View and works everything pending, so waking it twenty times for a
    /// page of twenty events would do the same work twenty times over and collide with itself on the way. A
    /// subscription naturally coalesces a burst into a single wakeup, which forwarding does not: that fires
    /// once per event.
    ///
    /// Nothing here reads an event payload. The page says *something happened, go look*; the trigger then
    /// decides from the View. Reach into <c>page.Events</c> for data and this stops being an automation and
    /// becomes an event handler with extra steps.
    /// </summary>
    public async Task<IChangeListener> ProcessEventsAsync(
        EventRange page,
        ISubscriptionController controller,
        IDocumentOperations operations,
        CancellationToken cancellationToken)
    {
        if (page.Events.Count == 0) return NullChangeListener.Instance;

        // IServiceProvider, resolved PER PAGE — not IMessageBus by constructor injection, which deadlocks.
        //
        // Marten builds this subscription during store construction, and Wolverine's message store IS Marten.
        // Taking IMessageBus in the constructor therefore makes MessageBus reach for WolverineRuntime.Storage
        // while that Lazy is still being created:
        //
        //     InvalidOperationException: ValueFactory attempted to access the Value property of this instance.
        //
        // A circular startup, and nothing in the docs warns of it. Resolving when a page arrives puts the
        // lookup safely after everything is initialised.
        await using var scope = services.CreateAsyncScope();
        await scope.ServiceProvider.GetRequiredService<IMessageBus>()
            .InvokeAsync(new RunSendEmail(), cancellationToken);

        return NullChangeListener.Instance;
    }

    public ValueTask DisposeAsync() => new();
}
